import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const pendingFor = async (h: any, p: string) => (await h.pendingEffects()).filter((e: any) => e.from === p);

test('authorize, approve, capture, refund', async () => {
  const h = await createHost();
  assert.deepEqual(await h.authorize('p', 2), { ok: true });
  assert.equal((await h.authorize('p', 1)).ok, false);
  assert.equal((await h.authorize('q', 3)).ok, false);
  assert.equal(await h.payment('q'), null);
  const [e] = await pendingFor(h, 'p');
  assert.equal(e.kind, 'card.authorize');
  assert.deepEqual(e.data, { amount: 2 });
  assert.equal((await h.capture('p', 1)).ok, false);
  await h.completeEffect(e.id, 'ok');
  assert.equal((await h.pendingEffects()).length, 0);
  assert.equal((await h.payment('p'))!.status, 'authorized');
  assert.equal((await h.capture('p', 3)).ok, false);
  assert.deepEqual(await h.capture('p', 2), { ok: true });
  assert.deepEqual(await h.refund('p', 1), { ok: true });
  assert.equal((await h.refund('p', 2)).ok, false);
  assert.deepEqual(await h.payment('p'), { status: 'captured', authorized: 2, captured: 2, refunded: 1, requests: 1 });
  assert.deepEqual(await h.refund('p', 1), { ok: true });
  assert.equal((await h.payment('p'))!.status, 'refunded');
  assert.equal((await h.void('nope')).ok, false);
  (h as any).__dispose?.();
});

test('timeouts, late answers, failure', async () => {
  const h = await createHost();
  await h.authorize('p', 1);
  assert.deepEqual(await h.timedOut('p'), { ok: true });
  assert.deepEqual(await h.timedOut('p'), { ok: true });
  assert.equal((await pendingFor(h, 'p')).length, 3);
  assert.deepEqual(await h.timedOut('p'), { ok: true });
  assert.equal((await h.payment('p'))!.status, 'failed');
  assert.equal((await h.payment('p'))!.requests, 3);
  assert.equal((await h.timedOut('p')).ok, false);
  const [e] = await pendingFor(h, 'p');
  await h.completeEffect(e.id, 'ok');
  assert.equal((await h.payment('p'))!.status, 'failed');
  assert.equal((await pendingFor(h, 'p')).length, 2);

  await h.authorize('d', 1);
  await h.timedOut('d');
  const es = await pendingFor(h, 'd');
  await h.completeEffect(es[1].id, 'failed');
  assert.equal((await h.payment('d'))!.status, 'declined');
  await h.completeEffect(es[0].id, 'ok');
  assert.equal((await h.payment('d'))!.status, 'declined');

  await h.authorize('v', 2);
  await h.completeEffect((await pendingFor(h, 'v'))[0].id, 'ok');
  assert.deepEqual(await h.void('v'), { ok: true });
  assert.equal((await h.capture('v', 1)).ok, false);
  assert.equal((await h.increase('v')).ok, false);
  assert.equal((await h.expire('v')).ok, false);

  await h.authorize('x', 1);
  assert.equal((await h.expire('x')).ok, false);
  await h.completeEffect((await pendingFor(h, 'x'))[0].id, 'ok');
  assert.deepEqual(await h.increase('x'), { ok: true });
  assert.deepEqual(await h.expire('x'), { ok: true });
  for (const r of [h.capture('x', 1), h.void('x'), h.increase('x'), h.expire('x'), h.refund('x', 1), h.timedOut('x')]) assert.equal((await r).ok, false);
  assert.deepEqual(await h.payment('x'), { status: 'expired', authorized: 2, captured: 0, refunded: 0, requests: 1 });

  await h.authorize('i', 2);
  assert.equal((await h.increase('i')).ok, false);
  await h.completeEffect((await pendingFor(h, 'i'))[0].id, 'ok');
  assert.deepEqual(await h.increase('i'), { ok: true });
  assert.equal((await h.increase('i')).ok, false);
  assert.equal((await h.capture('i', 4)).ok, false);
  assert.deepEqual(await h.capture('i', 3), { ok: true });
  assert.equal((await h.increase('i')).ok, false);
  assert.equal((await h.expire('i')).ok, false);
  assert.deepEqual(await h.refund('i', 2), { ok: true });
  assert.deepEqual(await h.refund('i', 1), { ok: true });
  assert.deepEqual(await h.payment('i'), { status: 'refunded', authorized: 3, captured: 3, refunded: 3, requests: 1 });
  assert.deepEqual(await h.payment('v'), { status: 'voided', authorized: 2, captured: 0, refunded: 0, requests: 1 });
  (h as any).__dispose?.();
});
